solutions.go:
import "strings"

func kapitalKata(s string) string {
	kata := strings.Split(s, " ")
	for i, k := range kata {
		if k != "" {
			huruf := []rune(strings.ToLower(k))
			kata[i] = strings.ToUpper(string(huruf[0])) + string(huruf[1:])
		}
	}
	return strings.Join(kata, " ")
}
